#include <stdio.h>
#include <string.h>

#define MAX_LEN 64

int main(int argc, char *argv[])
{
    if (argc != 3) {
        puts("USAGE");
        return 0;
    }
    const char *pattern = argv[1];
    const char *text = argv[2];
    if (strlen(pattern) >= MAX_LEN) {
        puts("USAGE");
        return 0;
    }
    int m = (int)strlen(pattern);
    int n = (int)strlen(text);
    int dp[MAX_LEN + 1][MAX_LEN + 1] = {0};
    dp[0][0] = 1;
    for (int i = 1; i <= m; ++i) {
        if (pattern[i - 1] == '*')
            dp[i][0] = dp[i - 1][0];
        else
            dp[i][0] = 0;
    }
    for (int i = 1; i <= m; ++i) {
        for (int j = 1; j <= n; ++j) {
            char pc = pattern[i - 1];
            char tc = text[j - 1];
            if (pc == '*') {
                dp[i][j] = dp[i - 1][j] || dp[i][j - 1];
            } else if (pc == '?' || pc == tc) {
                dp[i][j] = dp[i - 1][j - 1];
            } else {
                dp[i][j] = 0;
            }
        }
    }
    puts(dp[m][n] ? "MATCH" : "NO_MATCH");
    return 0;
}
